import itertools
from hypothesis import given, strategies as st
from solution import minPath


# ---------- reference model (obviously correct brute force) ----------

def _neighbors(i, j, n):
    res = []
    if i > 0:
        res.append((i - 1, j))
    if i < n - 1:
        res.append((i + 1, j))
    if j > 0:
        res.append((i, j - 1))
    if j < n - 1:
        res.append((i, j + 1))
    return res


def brute_min_path(grid, k):
    n = len(grid)
    # all walks of k cells, collect value lists
    best = None
    # stack of (i, j, values_list)
    stack = []
    for i in range(n):
        for j in range(n):
            stack.append((i, j, [grid[i][j]]))
    while stack:
        i, j, vals = stack.pop()
        if len(vals) == k:
            if best is None or vals < best:
                best = vals
            continue
        for ni, nj in _neighbors(i, j, n):
            stack.append((ni, nj, vals + [grid[ni][nj]]))
    return best


def _pos_of(grid, v):
    n = len(grid)
    for i in range(n):
        for j in range(n):
            if grid[i][j] == v:
                return (i, j)
    raise AssertionError("value not found")


def _is_valid_walk(grid, vals):
    n = len(grid)
    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)
    for v in vals:
        if v not in pos:
            return False
    for a, b in zip(vals, vals[1:]):
        ia, ja = pos[a]
        ib, jb = pos[b]
        if abs(ia - ib) + abs(ja - jb) != 1:
            return False
    return True


def _min_neighbor_of_one(grid):
    n = len(grid)
    x, y = _pos_of(grid, 1)
    vals = []
    for nx, ny in _neighbors(x, y, n):
        vals.append(grid[nx][ny])
    return min(vals) if vals else None


@st.composite
def grid_and_k(draw, n_min=2, n_max=3, k_min=1, k_max=5):
    n = draw(st.integers(min_value=n_min, max_value=n_max))
    flat = draw(st.permutations(list(range(1, n * n + 1))))
    grid = [list(flat[i * n:(i + 1) * n]) for i in range(n)]
    k = draw(st.integers(min_value=k_min, max_value=k_max))
    return (grid, k)


# ---------- explicit spec examples ----------

def test_spec_example_1():
    grid = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    assert minPath(grid, 3) == [1, 2, 1]


def test_spec_example_2():
    grid = [[5, 9, 3], [4, 1, 6], [7, 8, 2]]
    assert minPath(grid, 1) == [1]


# ---------- properties ----------

@given(grid_and_k())
def test_matches_brute_force_reference(arg):
    grid, k = arg
    assert minPath(grid, k) == brute_min_path(grid, k)


@given(grid_and_k())
def test_output_length_equals_k(arg):
    grid, k = arg
    assert len(minPath(grid, k)) == k


@given(grid_and_k())
def test_values_within_range(arg):
    grid, k = arg
    n = len(grid)
    out = minPath(grid, k)
    for v in out:
        assert 1 <= v <= n * n


@given(grid_and_k())
def test_first_element_is_global_minimum(arg):
    grid, k = arg
    out = minPath(grid, k)
    assert out[0] == 1


@given(grid_and_k(k_min=2, k_max=5))
def test_second_element_is_min_neighbor_of_one(arg):
    grid, k = arg
    out = minPath(grid, k)
    assert out[1] == _min_neighbor_of_one(grid)


@given(grid_and_k())
def test_path_corresponds_to_valid_walk(arg):
    grid, k = arg
    out = minPath(grid, k)
    assert _is_valid_walk(grid, out)


@given(grid_and_k())
def test_result_is_lexicographically_minimal(arg):
    grid, k = arg
    out = minPath(grid, k)
    # out must be <= every brute-force candidate; check a sample:
    # the brute minimum itself
    assert out == brute_min_path(grid, k)
    # and explicitly no neighbor deviation gives smaller prefix
    n = len(grid)
    # any path starting with value > 1 is larger
    assert out < [2] * k or out == [1] + out[1:]


def test_left_edge_does_not_wrap_around():
    # 1 at (0,0); true neighbors are 8 and 9, wrap cell (0,2) holds 2.
    # Correct answer must use 8, buggy wrap-around would use 2 (invalid walk).
    grid = [[1, 8, 2], [9, 7, 6], [4, 5, 3]]
    assert brute_min_path(grid, 2) == [1, 8]
    assert minPath(grid, 2) == [1, 8]
    assert minPath(grid, 3) == [1, 8, 1]


def test_left_edge_middle_row_no_wrap():
    # 1 at (1,0); wrap cell (1,2) holds 2, true neighbors are large.
    grid = [[9, 8, 7], [1, 6, 2], [5, 4, 3]]
    # neighbors of 1: (0,0)=9, (2,0)=5, (1,1)=6 -> min 5
    assert brute_min_path(grid, 2) == [1, 5]
    assert minPath(grid, 2) == [1, 5]
    assert minPath(grid, 4) == [1, 5, 1, 5]


def test_one_at_corner_bottom_left_no_wrap():
    grid = [[9, 8, 7], [6, 5, 4], [1, 3, 2]]
    # 1 at (2,0); neighbors (1,0)=6,(2,1)=3 -> min 3; wrap (2,2)=2 must be ignored
    assert brute_min_path(grid, 2) == [1, 3]
    assert minPath(grid, 2) == [1, 3]


@given(grid_and_k(k_min=1, k_max=1))
def test_k_equals_one_always_singleton_one(arg):
    grid, k = arg
    assert minPath(grid, k) == [1]


def test_oscillation_between_one_and_min_neighbor():
    # For any k, the unique optimum must alternate 1, mn, 1, mn, ...
    # because 1 is the global minimum.
    grid = [[5, 9, 3], [4, 1, 6], [7, 8, 2]]
    mn = _min_neighbor_of_one(grid)
    for k in [1, 2, 3, 4, 5, 10]:
        expected = [1 if i % 2 == 0 else mn for i in range(k)]
        assert minPath(grid, k) == expected == brute_min_path(grid, k)
